import React, { useEffect, useState } from "react";
import NavbarPlayer from "./components/NavbarPlayer";
import "./Feed.css";
import axios from "axios";

const Feed = () => {
  const [questions, setQuestions] = useState([]); // سوالات از طراحان دنبال‌شده
  const [error, setError] = useState(""); // مدیریت خطاها
  const currentUserId = 1; // شناسه کاربر لاگین‌شده (باید از localStorage یا سیستم احراز هویت دریافت شود)

  // دریافت سوالات از طراحانی که کاربر دنبال می‌کند
  const fetchFeedQuestions = async () => {
    try {
      const response = await axios.get("http://localhost:8080/followed-designers-questions", {
        params: { userId: currentUserId },
      });
      if (response.data.responseHeader === "OK") {
        setQuestions(response.data.dto.questions || []);
        setError("");
      } else {
        setError("خطا در دریافت سوالات.");
      }
    } catch (err) {
      console.error("Error fetching feed questions:", err);
      setError("خطا در برقراری ارتباط با سرور.");
    }
  };

  // ارسال پاسخ به سوال
  const handleAnswer = async (questionId, selectedOption) => {
    try {
      const response = await axios.post("http://localhost:8080/submit-answer", null, {
        params: {
          userId: currentUserId,
          questionId,
          selectedOption,
        },
      });
      if (response.data.responseHeader === "OK") {
        alert("پاسخ شما با موفقیت ارسال شد.");
      } else {
        alert("خطا در ارسال پاسخ.");
      }
    } catch (err) {
      console.error("Error submitting answer:", err);
      alert("خطا در ارسال پاسخ.");
    }
  };

  // دریافت سوالات هنگام لود صفحه
  useEffect(() => {
    fetchFeedQuestions();
  }, []);

  return (
    <div className="main-container">
      <NavbarPlayer />

      <button
        id="dark-mode-toggle"
        className="dark-mode-btn"
        onClick={() => document.body.classList.toggle("dark-mode")}
      >
        <span id="icon">🌞</span>
      </button>

      <div className="feed-container">
        <h2>فید سوالات</h2>
        {error && <p className="error-message">{error}</p>}
        {questions.map((question, index) => (
          <div key={index} className="question-item">
            <h3>متن سوال: {question.text}</h3>
            {question.options.map((option, i) => (
              <button
                key={i}
                className="option-btn"
                onClick={() => handleAnswer(question.id, i + 1)}
              >
                {option}
              </button>
            ))}
            <p>دسته‌بندی: {question.category}</p>
            <p>درجه دشواری: {question.difficulty}</p>
          </div>
        ))}
        {questions.length === 0 && !error && <p>هیچ سوالی برای نمایش وجود ندارد.</p>}
      </div>
    </div>
  );
};

export default Feed;
